(async()=>{const target=document.getElementById('v4-context');try{const res=await fetch('/api/status');if(res.status===401){location.replace('/login');return;}if(!res.ok)throw Error('O serviço está temporariamente indisponível.');const status=await res.json();if(!status.ready)throw Error('Acesso confirmado. A primeira carga dos indicadores ainda está em preparação.');for(const file of ['data.js','strategic-decisions.js','core.js','app.js','v4.js','admin.js','contracts-admin.js'])await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=file;s.onload=resolve;s.onerror=()=>reject(Error('Não foi possível carregar os indicadores. Entre novamente.'));document.body.append(s);});const logout=document.createElement('button');logout.className='btn';logout.textContent='Sair';logout.onclick=async()=>{const r=await fetch('/api/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(r.ok)location.replace('/login');};document.querySelector('.sb').append(logout);}catch(e){target.textContent=e.message;target.setAttribute('role','alert');}})();